function writeBatch(name, rows) {
  const out = rows.map(([id, literal, idiomatic]) => ({ id, literal, idiomatic }));
  const path = `/workspace/translations/_weishu009_${name}.json`;
  fs.writeFileSync(path, JSON.stringify(out, null, 2) + '\n');
  console.log(`${name}: ${out.length} sentences → ${path}`);
}

writeBatch('b1', b1);
writeBatch('b2', b2);
writeBatch('b3', b3);

const all = [...b1, ...b2, ...b3];
const ids = new Set(all.map((r) => r[0]));
if (all.length !== 300) throw new Error(`Expected 300, got ${all.length}`);
if (ids.size !== 300) throw new Error('Duplicate ids');
console.log('Total:', all.length, 'sentences s0001–s0300');
